import{_ as d,y as s,a as i,o as e,a4 as a,c as n,w as r,I as h,D as p,a5 as c}from"./chunks/framework.-FZumj2l.js";const _=JSON.parse('{"title":"Cart Workflow (Shop)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/cart.md","filePath":"api/workflows/shop/cart.md","lastUpdated":1783327468000}'),l={name:"api/workflows/shop/cart.md"};function u(m,t,g,f,k,b){const o=s("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="cart-workflow-shop" tabindex="-1">Cart Workflow (Shop) <a class="header-anchor" href="#cart-workflow-shop" aria-label="Permalink to &quot;Cart Workflow (Shop)&quot;">​</a></h1><p>Build a cart for a guest or a logged-in customer: create/obtain the cart, add and update items, apply coupons, and merge a guest cart into the customer cart at login.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Storefront key</strong> — ask the user; send it as the storefront key header on every Shop request. Never invent it.</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A valid storefront key (<a href="/api/setup.html">Setup</a>, <a href="/api/authentication.html">Authentication</a>).</li><li>For the customer path: a logged-in customer (<a href="/api/rest-api/shop/customers.html">Customer login</a>).</li></ul><p><strong>When does a merge happen?</strong> A guest adds items to a guest cart, then decides to log in. On login you call <strong>mergeCart</strong> with the guest cart token — the guest cart&#39;s items are merged into the customer&#39;s own cart so nothing is lost.</p><h2 id="dependency-diagram" tabindex="-1">Dependency diagram <a class="header-anchor" href="#dependency-diagram" aria-label="Permalink to &quot;Dependency diagram&quot;">​</a></h2>',8)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20key%5BStorefront%20key%3Cbr%2F%3Eask%20user%5D%20--%3E%20who%7BCustomer%3Cbr%2F%3Elogged%20in%3F%7D%0A%20%20who%20--%20guest%20--%3E%20gcart%5BPOST%20create-cart%3Cbr%2F%3Eguest%20cart%20token%5D%0A%20%20who%20--%20customer%20--%3E%20login%5BPOST%20customer%20login%5D%0A%20%20gcart%20--%3E%20add%5BPOST%20add-to-cart%5D%0A%20%20add%20--%3E%20decide%7BGuest%20logs%3Cbr%2F%3Ein%20later%3F%7D%0A%20%20decide%20--%20yes%20--%3E%20merge%5BmergeCart%3Cbr%2F%3Eguest%20cart%20into%20customer%20cart%5D%0A%20%20decide%20--%20no%20--%3E%20upd%0A%20%20login%20--%3E%20merge%0A%20%20merge%20--%3E%20upd%5BPOST%20update-cart-item%5D%0A%20%20add%20--%3E%20coupon%5BPOST%20apply-coupon%5D%0A%20%20upd%20--%3E%20read%5BGET%20get-cart%5D%0A%20%20coupon%20--%3E%20read%0A"})]),fallback:r(()=>t[0]||(t[0]=[h(" Loading... ",-1)])),_:1})),t[2]||(t[2]=a('<h2 id="ordered-call-table" tabindex="-1">Ordered call table <a class="header-anchor" href="#ordered-call-table" aria-label="Permalink to &quot;Ordered call table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Endpoint</th><th>Depends on</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td>Create guest cart</td><td><a href="/api/rest-api/shop/cart/create-cart.html">POST create-cart</a> · <a href="/api/graphql-api/shop/cart.html">GraphQL</a></td><td>storefront key</td><td>Guest path only; returns a cart token</td></tr><tr><td>2</td><td>Customer login</td><td><a href="/api/rest-api/shop/customers/customer-login.html">POST login</a></td><td>storefront key</td><td>Customer path; after login, merge the guest cart (step 3)</td></tr><tr><td>3</td><td>Merge guest cart</td><td><a href="/api/rest-api/shop/cart/merge-cart.html">POST merge-cart</a> · <a href="/api/graphql-api/shop/mutations/merge-cart.html">GraphQL</a></td><td>a guest cart id + a logged-in customer (customer Bearer token)</td><td>Merges the guest cart&#39;s items into the customer cart so nothing is lost</td></tr><tr><td>4</td><td>Add item</td><td><a href="/api/rest-api/shop/cart/add-to-cart.html">POST add-to-cart</a> · <a href="/api/graphql-api/shop/cart.html">GraphQL</a></td><td>cart (guest token or logged-in customer)</td><td>Same endpoint for both paths</td></tr><tr><td>5</td><td>Update item qty</td><td><a href="/api/rest-api/shop/cart/update-cart-item.html">POST update-cart-item</a></td><td>an item in the cart</td><td></td></tr><tr><td>6</td><td>Apply coupon</td><td><a href="/api/rest-api/shop/cart/apply-coupon.html">POST apply-coupon</a></td><td>an item in the cart</td><td>Remove with <a href="/api/rest-api/shop/cart/remove-coupon.html">remove-coupon</a></td></tr><tr><td>7</td><td>Read cart</td><td><a href="/api/rest-api/shop/cart/get-cart.html">GET get-cart</a> · <a href="/api/graphql-api/shop/cart.html">GraphQL</a></td><td>any cart mutation</td><td>Totals, items, applied coupon</td></tr></tbody></table><h2 id="end-to-end-example" tabindex="-1">End-to-end example <a class="header-anchor" href="#end-to-end-example" aria-label="Permalink to &quot;End-to-end example&quot;">​</a></h2><p>Guest: create-cart → add-to-cart → apply-coupon → get-cart. Guest who then logs in: create-cart (guest) → add-to-cart → login → <strong>mergeCart</strong> → get-cart. Follow each linked page for the exact request/response body (REST and GraphQL).</p><h2 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h2><p>To change cart behavior on the server, see <a href="/api/workflows/customization/">Customization → Shop</a>.</p>',6))])}const T=d(l,[["render",u]]);export{_ as __pageData,T as default};
